let active='All',selected=0;const tiles=[];
entries.forEach((entry,i)=>{const b=document.createElement('button');b.className='tile';b.setAttribute('aria-label',`Explore ${entry.name}`);b.innerHTML=`<canvas width="360" height="300" aria-hidden="true"></canvas><span class="tile-label"></span><span class="tile-family"></span>`;b.querySelector('.tile-label').textContent=entry.name;b.querySelector('.tile-family').textContent=entry.family;b.onclick=()=>open(i);grid.append(b);draw(b.querySelector('canvas'),i);tiles.push(b)});
function filter(name){active=name;tiles.forEach((b,i)=>b.hidden=name!=='All'&&entries[i].family!==name);document.querySelectorAll('#filters button').forEach(b=>b.setAttribute('aria-pressed',String(b.textContent===name)));$('#count').textContent=`${tiles.filter(b=>!b.hidden).length} / ${entries.length} VISUAL STUDIES`}
['All',...groups.map(g=>g[0])].forEach(name=>{const b=document.createElement('button');b.textContent=name;b.onclick=()=>filter(name);$('#filters').append(b)});filter('All');
function open(i){selected=(i+entries.length)%entries.length;const e=entries[selected];$('#detail-count').textContent=`STUDY ${String(selected+1).padStart(2,'0')} / 40`;$('#detail-family').textContent=e.family;$('#detail-title').textContent=e.name;$('#detail-description').textContent=e.description;$('#source').href=source;draw($('#large'),selected,phase);if(!dialog.open)dialog.showModal();studyLink(dialog,'recipe',e.name)}
$('#close').onclick=()=>dialog.close();$('#previous').onclick=()=>open(selected-1);$('#next').onclick=()=>open(selected+1);dismissOnOutsideTouch(dialog);
const reduce=matchMedia('(prefers-reduced-motion: reduce)'),motion=$('#motion'),visible=new Set();let playing=!reduce.matches,phase=0,last=0,paint=0,userChoice=false;
function motionLabel(){motion.textContent=playing?'Pause motion':'Play motion';motion.setAttribute('aria-pressed',String(playing))}
motionLabel();motion.onclick=()=>{userChoice=true;playing=!playing;motionLabel()};reduce.addEventListener?.('change',()=>{if(!userChoice){playing=!reduce.matches;motionLabel()}});
if('IntersectionObserver'in window){const observer=new IntersectionObserver(items=>{for(const item of items){const i=tiles.indexOf(item.target);if(item.isIntersecting)visible.add(i);else visible.delete(i)}},{rootMargin:'80px'});tiles.forEach(tile=>observer.observe(tile))}else tiles.forEach((_,i)=>visible.add(i));
function animate(now){if(!last)last=now;if(playing&&!document.hidden){phase+=Math.min((now-last)/1000,.05);if(now-paint>110){for(const i of visible)if(!tiles[i].hidden)draw(tiles[i].querySelector('canvas'),i,phase);if(dialog.open)draw($('#large'),selected,phase);paint=now}}last=now;requestAnimationFrame(animate)}
